<script lang="ts">
	import { onMount } from 'svelte';
	type Scene = 'world' | 'market' | 'list' | 'match';
	let { scene = 'world', class: className = '', alt = '' }: { scene?: Scene; class?: string; alt?: string } = $props();
	let labelled = $derived(alt.length > 0);
	let element: SVGSVGElement;
	let visible = $state(false);
	let viewBox = $derived(scene === 'list' ? '115 205 430 340' : scene === 'market' ? '140 180 690 400' : '0 0 900 600');
	onMount(() => {
		const observer = new IntersectionObserver(([entry]) => { visible = entry.isIntersecting; }, { rootMargin: '80px' });
		observer.observe(element);
		return () => observer.disconnect();
	});
</script>

